function renderCheckout(){
 const r=getRide(),root=$b('checkoutBody');
 if(!r){root.innerHTML='<p class="market-empty">Selecciona una salida publicada para reservar.</p>';return;}
 const count=Number($b('people').value)||1,seats=mode==='private'?r.capacity:count,signature=r.id+':'+seats+':'+mode+':'+count;
 if(checkoutBuilt===signature&&$b('checkoutForm'))return;
 checkoutBuilt=signature;demoPaymentStage='method';
 const pending=pendingPayment?.rideId===r.id&&pendingPayment.seats===seats&&pendingPayment.mode===mode?pendingPayment:null;
 checkout=pending||{rideId:r.id,requestId:crypto.randomUUID(),bookingToken:randomToken(),seats,mode,quotedPriceCents:r.priceCents,passengers:[],paymentMethod:'credit'};
 demoSelectedSeats=Array.isArray(checkout.seatNumbers)?checkout.seatNumbers.filter(n=>Number.isInteger(n)&&n>=1&&n<=r.capacity&&!r.reservedSeatNumbers?.includes(n)):[];
 const chooser=mode==='private'?'<h2 class="market-h2">Tu horario de salida</h2><label class="field">Fecha elegida<input type="date" class="form-input" id="privateRouteDate" required value="'+esc(checkout.privateDate||$b('date').value)+'"></label><label class="field">Hora elegida<input type="time" class="form-input" id="privateRouteTime" required value="'+esc(checkout.privateTime||'09:00')+'"></label><label class="field">Dirección de recogida<input class="form-input" id="privateRoutePickup" required value="'+esc(checkout.pickupAddress||r.origin)+'"></label>':'<h2 class="market-h2">Selecciona tu asiento</h2><div id="demoSeatChooser" data-capacity="'+r.capacity+'">'+demoSeatLayout(r.capacity)+'</div>';
 root.innerHTML='<span class="tag">CHECKOUT FICTICIO</span><h1 class="checkout-title">Confirma tu viaje.</h1><p class="sub">Demostración. No introduzcas información bancaria real.</p><div class="checkout-summary"><strong>'+esc(r.origin)+' → '+esc(r.destination)+'</strong><p>'+esc(r.operatorName)+' · '+esc(r.vehicle)+' · '+esc(r.date)+' · '+esc(r.time)+'</p><p>'+seats+' plaza(s) · '+r.available+' disponibles</p></div><form id="checkoutForm" onsubmit="event.preventDefault();BookingApp.demoPaymentContinue()"><h2 class="market-h2">Pasajeros</h2>'+Array.from({length:count},(_,i)=>'<label class="field">Pasajero '+(i+1)+'<input class="form-input passenger-name" required minlength="2" maxlength="80" value="'+esc(checkout.passengers[i]||'Juan Pérez')+'"></label>').join('')+chooser+'<div id="demoPaymentMethodStep"><h2 class="market-h2">Método de pago</h2><div class="payment-methods">'+[['credit','Tarjeta de crédito'],['debit','Tarjeta de débito'],['transfer','Transferencia bancaria']].map(([v,label])=>'<label><input type="radio" name="demoPayment" value="'+v+'" '+(checkout.paymentMethod===v?'checked':'')+'>'+label+'</label>').join('')+'</div><button type="submit" class="yellow" style="width:100%">Continuar al pago →</button></div><div id="demoPaymentDetailsStep" hidden><div id="demoPaymentDetails"></div><div class="checkout-total"><span>Total simulado</span><strong>'+money(r.priceCents*seats)+'</strong></div><p id="checkoutError" class="checkout-error" role="alert"></p><button type="button" id="confirmDemoPayment" class="yellow" style="width:100%" onclick="BookingApp.pay()">Simular pago y confirmar reserva</button><button type="button" class="security-link" onclick="BookingApp.demoPaymentBack()">← Cambiar método de pago</button></div></form>';
}
function demoPaymentBack(){demoPaymentStage='method';$b('demoPaymentMethodStep').hidden=false;$b('demoPaymentDetailsStep').hidden=true;}
async function pay(){if(payBusy||!checkout)return;const form=$b('checkoutForm');if(!form.reportValidity())return;payBusy=true;const button=$b('confirmDemoPayment');button.disabled=true;button.textContent='Confirmando reserva…';$b('checkoutError').textContent='';checkout.passengers=Array.from(document.querySelectorAll('.passenger-name'),e=>e.value.trim());checkout.paymentMethod=document.querySelector('[name="demoPayment"]:checked').value;checkout.seatNumbers=mode==='private'?null:demoSelectedSeats.slice();pendingPayment=checkout;save('rutasec-pending-checkout',pendingPayment);try{const result=await api(mode==='private'?'/api/private-route-bookings':'/api/bookings',{body:{date:checkout.privateDate,time:checkout.privateTime,pickupAddress:checkout.pickupAddress,rideId:checkout.rideId,requestId:checkout.requestId,bookingToken:checkout.bookingToken,seats:checkout.seats,mode:checkout.mode,quotedPriceCents:checkout.quotedPriceCents,passengers:checkout.passengers,paymentMethod:checkout.paymentMethod,seatNumbers:checkout.seatNumbers}});rememberTicket(result.booking.id,checkout.bookingToken);pendingPayment=null;localStorage.removeItem('rutasec-pending-checkout');activeTicket=result.booking;activeTicketToken=checkout.bookingToken;ticketRenderKey='';history.unshift(result.booking);const url=ticketLink(result.booking,checkout.bookingToken);location.hash=new URL(url).hash;show('ticket');renderTicket();await loadCatalog();notify('Pago simulado confirmado. Boleto generado y cupos actualizados.');}catch(error){$b('checkoutError').textContent=error.message;await loadCatalog();if(error.status===409&&/precio cambió/i.test(error.message)){pendingPayment=null;localStorage.removeItem('rutasec-pending-checkout');checkoutBuilt='';renderCheckout();$b('checkoutError').textContent='El precio cambió. Revisa el nuevo total y confirma de nuevo si deseas continuar.';}}finally{payBusy=false;if(button?.isConnected){button.disabled=false;button.textContent='Continuar';}}}
async function loadTicket(id,token){activeTicketToken=token||ticketKeys[id]||'';if(!activeTicketToken){$b('ticketBody').innerHTML='<p class="market-empty">Abre el enlace completo del boleto, que incluye su acceso privado.</p>';return;}try{const data=await api('/api/bookings/'+id,{token:activeTicketToken});activeTicket=data.booking;rememberTicket(id,activeTicketToken);renderTicket();}catch(error){$b('ticketBody').innerHTML='<p class="market-empty">'+esc(error.message)+'</p>';}}
function renderTicket(){if(!activeTicket)return;const b=activeTicket,i=b.itinerary,key=JSON.stringify(b);if(ticketRenderKey===key&&$b('ticketBody').dataset.ticket===b.id)return;ticketRenderKey=key;$b('ticketBody').dataset.ticket=b.id;const confirmed=b.status==='confirmed';$b('ticketBody').innerHTML='<div class="ticket-card"><span class="tag">BOLETO DE DEMOSTRACIÓN</span><h1>'+esc(i.origin)+' → '+esc(i.destination)+'</h1><div class="ticket-id">RESERVA '+esc(b.id)+'</div><dl><dt>SALIDA · ECUADOR</dt><dd>'+esc(i.date)+' · '+esc(i.time)+'</dd><dt>OPERADORA Y VEHÍCULO</dt><dd>'+esc(i.operatorName)+' · '+esc(i.vehicle)+'</dd><dt>ASIENTOS RESERVADOS</dt><dd>'+(b.seatNumbers?.length?b.seatNumbers.join(', '):b.seats)+(b.mode==='private'?' · Vehículo completo':'')+'</dd><dt>PUNTO DE EMBARQUE</dt><dd>'+esc(i.pickupAddress||i.origin)+'</dd><dt>INSTRUCCIONES</dt><dd>'+esc(i.pickupInstructions||'Presentarse 15 minutos antes.')+'</dd><dt>ESTADO DE LA RESERVA</dt><dd>'+(!confirmed?'Cancelada':b.ride.status==='finished'?'Viaje finalizado':'Confirmada')+'</dd></dl><ol class="ticket-passengers">'+b.passengers.map(p=>'<li>'+esc(p.name)+(p.seatNumber?' · Asiento '+p.seatNumber:'')+(p.boardedAt?' · Abordó':'')+'</li>').join('')+'</ol><div class="ticket-paid">'+(confirmed?'✓ PAGO SIMULADO CONFIRMADO':'PAGO SIMULADO REEMBOLSADO')+'<br>'+esc(payText[b.payment.method])+' · '+money(b.payment.amountCents)+'<br><small>Sin cargo bancario real.</small></div></div><p><a class="security-link" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(i.pickupLat!=null&&i.pickupLng!=null?i.pickupLat+','+i.pickupLng:i.pickupAddress||i.origin)+'">Abrir punto de embarque en Google Maps →</a></p><h2 class="market-h2">QR de embarque</h2><div id="boardingQRs"></div><div class="ticket-actions">'+(confirmed&&b.ride.liveId?'<button class="yellow" onclick="BookingApp.followTicket()">'+(b.ride.status==='finished'?'Ver recorrido finalizado':'Abrir viaje en curso')+'</button>':confirmed?'<p class="ticket-await">Esperando a que la operadora inicie el viaje. El seguimiento se habilitará automáticamente aquí.</p>':'')+(confirmed&&(b.ride.operatorWhatsApp&&b.ride.operatorWhatsApp!=='00000000')?'<a class="security-outline" id="notifyOperatorWhatsApp" href="'+esc(ticketWhatsApp(b,activeTicketToken))+'" target="_blank" rel="noopener noreferrer">Avisar a la operadora por WhatsApp</a>':'')+'<button class="security-outline" onclick="BookingApp.shareCurrentTicket()">Copiar enlace del boleto</button><button class="security-outline" onclick="window.print()">Imprimir boleto</button>'+(confirmed&&b.ride.status==='published'?'<button class="market-small danger" onclick="BookingApp.cancelCurrent()">Cancelar reserva demo</button>':'')+'</div><p class="market-note">El operador recibe esta reserva en su panel aunque no envíes WhatsApp. El mensaje se prepara; tú confirmas el envío.</p><p class="market-note">El enlace del boleto permite consultar nombres y reserva. Compártelo solo con las personas involucradas en esta demostración.</p>';renderBoardingQR();
}
