const move=(id,ids)=>ids.forEach(name=>{const el=$b(name);if(el)panels[id].appendChild(el)});
move('overview',['operatorTotals']);move('rides',['marketRideForm','operatorFilters','operatorRideList']);move('reservations',['operatorReservationsTitle','operatorReservations']);const privatePanel=document.createElement('div');privatePanel.id='operatorPrivateRequests';panels.reservations.appendChild(privatePanel);move('payments',['operatorSalesHistory']);move('scanner',['boardingScanner']);move('profile',['operatorProfileToggle','marketProfileForm']);if(!operatorAuth){panels.profile.appendChild($b('marketProfileForm'));}
const heading=(id,title)=>{const h=document.createElement('h2');h.className='market-h2';h.textContent=title;panels[id].prepend(h)};heading('overview','Resumen de operación');heading('livefleet','Centro de operaciones · En vivo');panels.livefleet.innerHTML += '<p class="market-note">Simulación visual · ocho unidades en la ruta Cuenca–Guayaquil. Las posiciones son ficticias y permanecen fijas.</p><div class="fleet-demo-legend"><span><i class="fleet-key fleet-out"></i> Cuenca → Guayaquil</span><span><i class="fleet-key fleet-back"></i> Guayaquil → Cuenca</span></div><div id="fleetDemoMap" class="fleet-demo-map" role="img" aria-label="Mapa simulado con ocho unidades entre Cuenca y Guayaquil"></div><div id="fleetDemoStats" class="fleet-demo-stats"></div><div id="fleetDemoUnits" class="fleet-demo-units"></div>';heading('resources','Flota y mantenimiento');heading('staff','Directorio de personal');heading('finance','Finanzas y facturación');heading('company','Administración empresarial');heading('rides','Mis viajes');heading('reservations','Reservas por viaje');heading('payments','Historial de cobros simulados');heading('scanner','Control de embarque');heading('profile','Datos de la operadora');heading('brand','Personalización de marca');panels.brand.insertAdjacentHTML('beforeend','<p class="market-note">Los cambios se publican para todos los pasajeros al guardar. Utiliza enlaces HTTPS de imágenes.</p><form id="operatorBrandForm" class="market-form" onsubmit="event.preventDefault();BookingApp.saveBrand()"><label class="field">Descripción comercial<textarea class="form-input" name="description" rows="3" maxlength="1200"></textarea></label><label class="field">URL HTTPS de portada<input class="form-input" name="cover" type="url" placeholder="https://..."></label><label class="field">URL HTTPS del logotipo<input class="form-input" name="logo" type="url" placeholder="https://..."></label><label class="field">Enlaces a fotografías (uno por línea)<textarea class="form-input" name="photos" rows="3"></textarea></label><button class="yellow">Guardar mi marca</button></form><div id="operatorBrandPreview"></div>');
const rideButton=Array.from(dashboard.querySelectorAll('button')).find(b=>b.textContent.trim()==='Crear nuevo viaje');if(rideButton)panels.rides.prepend(rideButton);
