function fleetDemoSelect(id){document.querySelectorAll('.fleet-demo-unit').forEach(el=>el.classList.toggle('selected',el.dataset.unit===id));const v=fleetDemoVehicles.find(x=>x.id===id);if(!v)return;const direction=v.direction==='out'?'Cuenca → Guayaquil':'Guayaquil → Cuenca';const arrival=String((Number(v.departure.slice(0,2))+3)%24).padStart(2,'0')+v.departure.slice(2);const card=$b('fleetDemoSelected');if(card)card.innerHTML='<div class="premium-person-card"><div class="premium-person-portrait"><img src="https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=240&q=75" alt="Fotografía ilustrativa de conductor"></div><div><span class="premium-eyebrow">UNIDAD '+esc(v.id)+' · SIMULACIÓN</span><h3>'+esc(v.driver)+'</h3><p>'+esc(direction)+'</p><dl><dt>Vehículo</dt><dd>'+esc(v.model||'Furgoneta')+'</dd><dt>Pasajeros</dt><dd>'+v.sold+' de '+v.seats+' asientos</dd><dt>Salida</dt><dd>'+v.departure+'</dd><dt>Llegada estimada</dt><dd>'+arrival+'</dd></dl>'+(v.id==='EC-103'?'<button type="button" class="premium-text-link" onclick="BookingApp.premiumDetail(\'staff\',\'P-01\')">Ver expediente de Juan Pauta →</button>':'')+'</div></div>';}
function premiumDetail(type,id){
 if(type!=='staff'&&type!=='vehicle')return;
 selectOperatorSection(type==='staff'?'staff':'resources');
 const root=$b(type==='vehicle'?'premiumVehicleDetail':'premiumStaffDetail');
 if(!root)return;
 const row=(label,value)=>'<dt>'+esc(label)+'</dt><dd>'+esc(value??'No registrado')+'</dd>';
 if(type==='staff'){
  const p=premiumStaff.find(x=>x.id===id);if(!p)return;
  const linked=premiumVehicles.find(v=>v.id===p.vehicle);
  root.innerHTML='<div class="premium-person-card"><img class="premium-profile-photo" src="'+esc(p.photo||'./assets/sedan.webp')+'" alt="Imagen ilustrativa"><div><span class="premium-eyebrow">PERSONAL · DEMOSTRACIÓN</span><h3>'+esc(p.name)+'</h3><p>'+esc(p.role)+'</p><dl>'+row('Ingreso',p.since)+row('Turno',p.shift)+row('Licencia',p.license)+row('Vehículo asignado',p.vehicle||'Sin asignación')+row('Estado','Registro de demostración')+'</dl>'+(linked?'<button type="button" class="premium-text-link" onclick="BookingApp.premiumDetail(\'vehicle\',\''+linked.id+'\')">Consultar vehículo '+esc(linked.id)+' →</button>':'')+'</div></div>';
 }else{
  const v=premiumVehicles.find(x=>x.id===id);if(!v)return;
  const assigned=premiumStaff.find(p=>p.vehicle===v.id);
  root.innerHTML='<div class="premium-person-card"><img class="premium-profile-photo" src="'+esc(v.photo||'./assets/sprinter.webp')+'" alt="Vehículo ilustrativo"><div><span class="premium-eyebrow">FLOTA · DEMOSTRACIÓN</span><h3>'+esc(v.id)+' · '+esc(v.model)+'</h3><dl>'+row('Placa',v.plate)+row('Kilometraje',v.km)+row('Próximo servicio',v.oil)+row('Capacidad',v.seats+' asientos')+row('Conductor asignado',assigned?.name||'Sin asignación')+'</dl>'+(assigned?'<button type="button" class="premium-text-link" onclick="BookingApp.premiumDetail(\'staff\',\''+assigned.id+'\')">Consultar expediente →</button>':'')+'</div></div>';
 }
 const selected=document.querySelector('.premium-directory-item[data-premium-id="'+id+'"]');
 if(selected){
  const directory=selected.closest('.premium-directory');
  directory.querySelectorAll('.premium-directory-item').forEach(btn=>{btn.classList.toggle('selected',btn===selected);btn.setAttribute('aria-expanded',String(btn===selected));});
  selected.insertAdjacentElement('afterend',root);
  root.hidden=false;
 }
 root.scrollIntoView({behavior:'smooth',block:'nearest'});
}
function renderPremiumPanels(){const panel=id=>document.querySelector('.operator-section[data-section="'+id+'"]');panel('resources').insertAdjacentHTML('beforeend','<p class="market-note">12 vehículos · 8 en ruta · 4 disponibles o en revisión. Datos de demostración.</p><div class="premium-directory">'+premiumVehicles.map(v=>'<button type="button" class="premium-directory-item" data-premium-id="'+v.id+'" aria-expanded="false" onclick="BookingApp.premiumDetail(\'vehicle\',\''+v.id+'\')"><span class="premium-unit-icon">▣</span><strong>'+v.id+'</strong><span>'+v.model+'</span><small>'+v.seats+' plazas</small></button>').join('')+'</div>');panel('staff').insertAdjacentHTML('beforeend','<p class="market-note">Directorio de personal. Selecciona Juan Pauta para consultar su expediente de demostración.</p><div class="premium-directory">'+premiumStaff.map(p=>'<button type="button" class="premium-directory-item" data-premium-id="'+p.id+'" aria-expanded="false" onclick="BookingApp.premiumDetail(\'staff\',\''+p.id+'\')"><span class="premium-unit-icon">◉</span><strong>'+p.name+'</strong><span>'+p.role+'</span><small>'+esc(p.vehicle||'Oficina')+'</small></button>').join('')+'</div>');panel('finance').insertAdjacentHTML('beforeend','<div class="premium-summary-grid"><article><small>Facturas SRI</small><strong>24</strong><span>Simulación · autorización pendiente de integración</span></article><article><small>Liquidaciones</small><strong>3</strong><span>Registros demostrativos</span></article><article><small>Gastos</small><strong>$420</strong><span>Combustible y mantenimiento · ficticio</span></article></div><h3>Facturación electrónica</h3><p class="market-note">Cada operadora configura su RUC y firma electrónica. La emisión automática mediante servicios del SRI pertenece a la segunda etapa; aquí no se emiten facturas reales.</p><div class="premium-ledger"><span>FAC-DEMO-001 · Viaje Cuenca–Guayaquil</span><b>Autorizada · simulación</b><span>FAC-DEMO-002 · Venta de pasaje</span><b>Pendiente · simulación</b></div>');panel('company').insertAdjacentHTML('beforeend','<div class="premium-summary-grid"><article><small>Personal</small><strong>3</strong><span>Expedientes y roles</span></article><article><small>Sucursales</small><strong>2</strong><span>Cuenca y Guayaquil · demo</span></article><article><small>Usuarios</small><strong>4</strong><span>Permisos por función</span></article></div><h3>Gestión de empresa</h3><p class="market-note">Personal, sucursales, usuarios, permisos y personalización de marca. La nómina y el historial laboral se consultan desde los expedientes.</p><button type="button" class="premium-text-link" onclick="BookingApp.operatorSection(\'staff\')">Abrir directorio de personal →</button><button type="button" class="premium-text-link" onclick="BookingApp.operatorSection(\'brand\')">Personalizar marca →</button>');const staff=panel('staff'),resources=panel('resources');const detail=document.createElement('div');detail.id='premiumStaffDetail';detail.className='premium-detail';staff.appendChild(detail);const vehicleDetail=document.createElement('div');vehicleDetail.id='premiumVehicleDetail';vehicleDetail.className='premium-detail';resources.appendChild(vehicleDetail);}
async function renderFleetDemo(){
 const root=$b('fleetDemoMap');if(!root)return;
 const stats=$b('fleetDemoStats');if(stats)stats.innerHTML='<div><small>Unidades en ruta</small><strong>8</strong></div><div><small>Cuenca → Guayaquil</small><strong>4</strong></div><div><small>Guayaquil → Cuenca</small><strong>4</strong></div>';
 const units=$b('fleetDemoUnits');if(units&&!units.children.length){units.innerHTML='<h3>Unidades en recorrido</h3><div id="fleetDemoSelected" aria-live="polite"></div>'+fleetDemoVehicles.map(v=>'<button type="button" class="fleet-demo-unit" data-unit="'+v.id+'" onclick="BookingApp.fleetDemoSelect(\''+v.id+'\')"><span class="fleet-demo-dot '+v.direction+'"></span><strong>'+v.id+'</strong><span>'+(v.direction==='out'?'Cuenca → Guayaquil':'Guayaquil → Cuenca')+'</span><small>'+v.sold+'/'+v.seats+' reservas</small></button>').join('');fleetDemoSelect('EC-101');}
 if(fleetDemoMap){setTimeout(()=>fleetDemoMap.invalidateSize(),0);return;}
 if(!window.L){root.textContent='No se pudo cargar el mapa. Revisa la conexión.';return;}
 const map=window.L.map(root,{zoomControl:true,scrollWheelZoom:false,attributionControl:true}).setView([-2.52,-79.48],9);fleetDemoMap=map;
 window.L.tileLayer('https://tile.openstreetmap.fr/hot/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors · HOT',maxZoom:19}).addTo(map);
 try{const response=await fetch('./shared/route.json');if(!response.ok)throw Error('Ruta no disponible');const route=await response.json();const coordinates=route.coordinates.map(([lng,lat])=>[lat,lng]);window.L.polyline(coordinates,{color:'#e9bc44',weight:4,opacity:.85}).addTo(map);
 const bounds=window.L.latLngBounds(coordinates);map.fitBounds(bounds.pad(.08));
 const indices=coordinates.length-1;
 fleetDemoVehicles.forEach(v=>{const at=Math.min(indices,Math.round(v.position*indices));const point=coordinates[at];const color=v.direction==='out'?'#e9bc44':'#39b7e5';const marker=window.L.marker(point,{icon:window.L.divIcon({className:'fleet-map-pin',html:'<span class="fleet-map-pulse '+v.direction+'"><span></span></span>',iconSize:[28,28],iconAnchor:[14,14]})}).addTo(map);marker.bindTooltip(v.id+' · '+v.driver);marker.on('click',()=>fleetDemoSelect(v.id));});
 }catch(error){root.insertAdjacentHTML('beforeend','<div class="fleet-map-warning">No se pudo cargar la geometría de la ruta.</div>');}
 setTimeout(()=>map.invalidateSize(),100);
}
function operatorSkeleton(){if(operatorBuilt)return;operatorBuilt=true;const option=cities.map(c=>'<option>'+esc(c)+'</option>').join('');$b('operatorBody').innerHTML='<span class="tag">PANEL DE DEMOSTRACIÓN</span><h1 class="page-title">Tu operación, al día.</h1><p class="market-note">Viajes, reservas y pagos simulados compartidos entre teléfonos.</p><button id="operatorProfileToggle" class="security-link" onclick="BookingApp.editOperatorProfile()" hidden>Editar operadora y WhatsApp</button><form id="marketProfileForm" class="market-form" onsubmit="event.preventDefault();BookingApp.saveOperator()"><h2>Operadora y WhatsApp</h2><label class="field">Nombre de la operadora<input id="marketOperatorName" class="form-input" minlength="2" maxlength="80" required placeholder="Nombre de tu operadora"></label><label class="field">WhatsApp para recibir avisos de reservas<input id="marketOperatorPhone" class="form-input" type="tel" required placeholder="+593 99 123 4567"></label><button id="saveOperatorProfile" class="yellow">Guardar operadora</button><p id="operatorProfileMessage" class="market-note" role="status">Configura tu operadora y el WhatsApp que recibirá los avisos de sus reservas. Este número se guarda previamente; no se solicita al pasajero durante el pago.</p></form><div id="operatorDashboard" hidden><div id="operatorTotals" class="market-summary"></div><button class="yellow" style="width:100%" onclick="BookingApp.newRide()">Crear nuevo viaje</button><form id="marketRideForm" class="market-form" onsubmit="event.preventDefault();BookingApp.saveRide()"><h2 id="rideFormTitle">Crear viaje</h2><div class="market-grid"><label class="field">Origen<select class="form-input" id="marketFrom" required>'+option+'</select></label><label class="field">Destino<select class="form-input" id="marketTo" required>'+option+'</select></label><label class="field">Fecha<input class="form-input" id="marketDate" type="date" required></label><label class="field">Hora<input class="form-input" id="marketTime" type="time" value="08:00" required></label></div><label class="field">Tipo de vehículo<select class="form-input" id="marketVehicleType" onchange="BookingApp.vehiclePreset(this.value)"><option value="van">Furgoneta grande</option><option value="minivan">Furgoneta pequeña</option><option value="suv">SUV</option><option value="auto">Auto sedán</option></select></label><label class="field">Vehículo<input class="form-input" id="marketVehicle" value="Mercedes Sprinter" required maxlength="80"></label><div class="market-grid"><label class="field">Capacidad<input class="form-input" id="marketCapacity" type="number" min="1" max="30" value="8" required></label><label class="field">Precio por asiento · USD<input class="form-input" id="marketPrice" type="number" min="1" max="1000" step="0.01" value="15" required></label></div><label class="field">Punto exacto de embarque<input class="form-input" id="marketPickupAddress" value="Terminal terrestre, Cuenca" required maxlength="160"></label><label class="field">Instrucciones de embarque<input class="form-input" id="marketPickupInstructions" value="Presentarse 15 minutos antes de la salida." maxlength="300"></label><div class="market-grid"><label class="field">Latitud (opcional)<input class="form-input" id="marketPickupLat" type="number" step="any" min="-90" max="90"></label><label class="field">Longitud (opcional)<input class="form-input" id="marketPickupLng" type="number" step="any" min="-180" max="180"></label></div><label class="market-check" id="marketPublishLabel"><input type="checkbox" id="marketPublish" checked>Publicar para que los pasajeros puedan reservar</label><p id="rideFormError" class="checkout-error" role="alert"></p><button id="saveMarketRide" class="yellow">Publicar viaje</button><button type="button" class="security-link" id="cancelRideEdit" onclick="BookingApp.cancelEdit()" hidden>Cancelar edición</button><p class="market-note">El recorrido simulado está disponible para Cuenca–Guayaquil.</p></form><h2 class="market-h2">Mis viajes</h2><div id="operatorFilters" class="market-controls">'+[['all','Todos'],['published','Publicados'],['upcoming','Próximos'],['running','En curso'],['finished','Finalizados'],['cancelled','Cancelados']].map(([v,t])=>'<button type="button" onclick="BookingApp.filterRides(\''+v+'\')" data-operator-filter="'+v+'" class="'+(v==='all'?'selected':'')+'">'+t+'</button>').join('')+'</div><div id="operatorRideList"></div><h2 class="market-h2">Control de embarque</h2><button type="button" class="yellow" onclick="BookingApp.openScanner()">Escanear boleto QR</button><p class="market-note">Verifica el QR y registra el embarque.</p><h2 class="market-h2" id="operatorReservationsTitle">Reservas por viaje</h2><div id="operatorReservations"></div><h2 class="market-h2">Historial de ventas simuladas</h2><div id="operatorSalesHistory"></div></div><p id="operatorSyncState" class="market-note" role="status"></p>';setupOperatorNavigation();$b('marketFrom').value='Cuenca';$b('marketTo').value='Guayaquil';$b('marketDate').value=$b('date').value;$b('marketDate').min=localDate(new Date());}
async function openOperator(){operatorSkeleton();updateOperatorTier();if(operatorAuth&&operatorTier!=='premium')await refreshOperator();}
async function saveOperator(){operatorSkeleton();const name=$b('marketOperatorName').value.trim(),whatsapp=$b('marketOperatorPhone').value.trim();if(!name||!whatsapp)return;const button=$b('saveOperatorProfile');button.disabled=true;try{if(!operatorAuth){operatorAuth={id:crypto.randomUUID(),token:randomToken()};save('rutasec-operator-access',operatorAuth);}await api('/api/operators',{body:{id:operatorAuth.id,name,whatsapp},token:operatorAuth.token});profileEditing=false;if($b('marketProfileForm')?.parentElement!==document.querySelector('.operator-section[data-section="profile"]'))document.querySelector('.operator-section[data-section="profile"]')?.appendChild($b('marketProfileForm'));operatorRenderKey='';await refreshOperator();$b('operatorProfileMessage').textContent='Operadora guardada. Este teléfono conserva el acceso a tu panel.';notify('Operadora lista para publicar viajes.');}catch(error){$b('operatorProfileMessage').textContent=error.message;}finally{button.disabled=false;}}
async function refreshOperator(){if(!operatorAuth)return;try{const data=await api('/api/operator',{token:operatorAuth.token});operatorData=data;lastOperatorError='';if(currentScreen()==='operator'){operatorSkeleton();if(!$b('marketOperatorName').value){$b('marketOperatorName').value=data.profile.name;$b('marketOperatorPhone').value=data.profile.whatsapp;}renderOperatorData();$b('operatorSyncState').textContent='● Sincronizado · las reservas llegan sin recargar';}}catch(error){lastOperatorError=error.message;if(currentScreen()==='operator')$b('operatorSyncState').textContent=error.message;}}
function renderOperatorData(){if(!operatorData)return;if(operatorTier==='premium')return;$b('operatorDashboard').hidden=false;if($b('operatorSubnav'))$b('operatorSubnav').hidden=false;updateOperatorTier();$b('marketProfileForm').hidden=!profileEditing;$b('operatorProfileToggle').hidden=false;$b('operatorProfileToggle').textContent=operatorData.profile.name+' · Editar operadora y WhatsApp';$b('marketRideForm').hidden=!rideFormOpen&&operatorData.rides.length>0;const d=operatorData,key=JSON.stringify({revision:d.revision,rides:d.rides,bookings:d.bookings,privateRequests:d.privateRequests});if(key===operatorRenderKey)return;operatorRenderKey=key;const privateRoot=$b('operatorPrivateRequests');if(privateRoot){const requests=d.privateRequests||[];privateRoot.innerHTML='<h2 class="market-h2">Solicitudes de transporte privado</h2>'+(requests.length?requests.map(p=>'<article class="operator-booking"><strong>'+esc(p.origin)+' → '+esc(p.destination)+'</strong><p>'+esc(p.passengerName)+' · '+esc(p.date)+' a '+esc(p.endDate)+' · '+esc(p.time)+' · '+p.people+' pasajero(s) · '+esc(p.vehicleType)+'</p><p>'+esc(p.pickupAddress)+' · '+esc(p.serviceType)+'</p><p>'+esc(p.notes||'Sin observaciones')+'</p><p>Estado: '+esc(p.status)+'</p>'+(p.status==='requested'?'<button class="market-small" onclick="BookingApp.claimPrivateRequest(\''+p.id+'\')">Asignar a mi operadora</button>':'<span class="market-status">Asignada a esta operadora</span>')+'</article>').join(''):'<p class="market-note">No hay solicitudes privadas pendientes.</p>');}const confirmed=d.bookings.filter(b=>b.status==='confirmed'&&!['finished','cancelled'].includes(b.ride.status)),gross=d.bookings.reduce((sum,b)=>sum+b.payment.amountCents,0),refunds=d.bookings.filter(b=>b.status==='cancelled').reduce((sum,b)=>sum+b.payment.amountCents,0);$b('operatorTotals').innerHTML='<div><small>Reservas activas</small><strong>'+confirmed.length+'</strong></div><div><small>Asientos reservados</small><strong>'+confirmed.reduce((sum,b)=>sum+b.seats,0)+'</strong></div><div><small>Ventas netas demo</small><strong>'+money(gross-refunds)+'</strong></div>';
 const rides=d.rides.filter(r=>operatorFilter==='all'||(operatorFilter==='upcoming'?r.status==='published'&&r.departsAt>=Date.now():r.status===operatorFilter));$b('operatorRideList').innerHTML=rides.length?rides.map(r=>{const count=d.bookings.filter(b=>b.rideId===r.id&&b.status==='confirmed').length;return '<article class="operator-ride"><span class="market-status '+(r.status==='cancelled'?'cancelled':'')+'">'+esc(statusText[r.status])+'</span><h3>'+esc(r.origin)+' → '+esc(r.destination)+'</h3><p>'+esc(r.date)+' · '+esc(r.time)+' · '+esc(r.vehicle)+'<br>'+money(r.priceCents)+' por asiento</p><strong class="capacity">'+r.available+' disponibles · '+r.occupied+' ocupados / '+r.capacity+'</strong><div class="seat-dots" aria-label="'+r.occupied+' asientos ocupados de '+r.capacity+'">'+Array.from({length:r.capacity},(_,i)=>'<i class="'+(i>=r.occupied?'free':'')+'"></i>').join('')+'</div><div class="market-controls"><button onclick="BookingApp.selectOperatorRide(\''+r.id+'\')">Ver reservas ('+count+')</button>'+(['published','draft'].includes(r.status)?'<button onclick="BookingApp.editRide(\''+r.id+'\')">Editar</button>':'')+(r.status==='draft'?'<button onclick="BookingApp.rideAction(\''+r.id+'\',\'publish\')">Publicar</button>':'')+(r.status==='published'?'<button onclick="BookingApp.copyRide(\''+r.id+'\')">Copiar enlace de salida</button><button '+(r.origin!=='Cuenca'||r.destination!=='Guayaquil'?'disabled':'')+' onclick="BookingApp.rideAction(\''+r.id+'\',\'start\')">Iniciar recorrido simulado</button>':'')+(r.liveId?'<button onclick="BookingApp.followOperator(\''+r.id+'\')">Ver recorrido</button>':'')+(r.status==='running'?'<button onclick="BookingApp.rideAction(\''+r.id+'\',\'finish\')">Finalizar viaje</button>':'')+(!['finished','cancelled'].includes(r.status)?'<button class="danger" onclick="BookingApp.rideAction(\''+r.id+'\',\'cancel\')">Cancelar viaje demo</button>':'')+'</div>'+(r.activeAlert?'<div class="operator-alert"><strong>SOS DE DEMOSTRACIÓN · '+(r.activeAlert.status==='attended'?'ATENDIDA':'ABIERTA')+'</strong><p>Alerta '+esc(r.activeAlert.id.slice(0,8))+' · '+r.activeAlert.position.lat.toFixed(5)+', '+r.activeAlert.position.lng.toFixed(5)+' · ubicación simulada</p>'+(r.activeAlert.status!=='attended'?'<button class="market-small" onclick="BookingApp.attendSOS(\''+r.id+'\')">Marcar SOS atendida</button>':'')+'</div>':'')+'</article>';}).join(''):'<p class="market-empty">No hay viajes en esta categoría.</p>';
 if(!operatorRideId&&d.rides.length)operatorRideId=d.rides.at(-1).id;renderReservations();$b('operatorSalesHistory').innerHTML='<p class="market-note">Ventas brutas: '+money(gross)+' · Reembolsos demo: '+money(refunds)+'</p>'+(d.bookings.length?d.bookings.toReversed().map(b=>'<div class="sales-entry"><strong>'+esc(b.id.slice(0,8).toUpperCase())+' · '+money(b.payment.amountCents)+'</strong><br>'+esc(b.itinerary.origin)+' → '+esc(b.itinerary.destination)+' · '+b.seats+' asiento(s)<br><small>'+esc(b.passengers.map(p=>p.name).join(', '))+' · '+(b.status==='cancelled'?'Cancelada · reembolso simulado':'Pago simulado confirmado')+'</small></div>').join(''):'<p class="market-note">Aún no hay ventas simuladas.</p>');
}
function renderReservations(){const r=operatorData?.rides.find(r=>r.id===operatorRideId);if(!r){$b('operatorReservations').innerHTML='<p class="market-note">Publica una salida para recibir reservas.</p>';return;}$b('operatorReservationsTitle').textContent='Reservas · '+r.origin+' → '+r.destination+' · '+r.time;const items=operatorData.bookings.filter(b=>b.rideId===r.id);$b('operatorReservations').innerHTML=items.length?items.map(b=>'<article class="operator-booking"><strong>Reserva '+esc(b.id.slice(0,8).toUpperCase())+' · '+b.seats+' asiento(s) · '+money(b.payment.amountCents)+'</strong><p>'+esc(b.id)+'<br>'+(b.status==='cancelled'?'Cancelada · reembolso simulado':'Pago SIMULADO CONFIRMADO · '+esc(payText[b.payment.method]))+'</p>'+b.passengers.map((p,i)=>'<div class="operator-passenger"><span>'+esc(p.name)+'</span>'+(p.boardedAt?'<span class="market-status">Abordó</span>':b.status==='confirmed'&&['published','running'].includes(r.status)?'<button class="market-small" onclick="BookingApp.board(\''+b.id+'\','+i+')">Marcar abordado</button>':'')+'</div>').join('')+(b.status==='confirmed'&&!['finished','cancelled'].includes(r.status)&&!b.passengers.some(p=>p.boardedAt)?'<button class="market-small danger" onclick="BookingApp.cancelBooking(\''+b.id+'\',true)">Cancelar reserva demo</button>':'')+'</article>').join(''):'<p class="market-note">Sin reservas todavía. Se mostrarán automáticamente cuando el pasajero confirme su pago simulado.</p>';}
function rideFields(){return {origin:$b('marketFrom').value,destination:$b('marketTo').value,date:$b('marketDate').value,time:$b('marketTime').value,vehicleType:$b('marketVehicleType').value,vehicle:$b('marketVehicle').value.trim(),capacity:Number($b('marketCapacity').value),priceCents:Math.round(Number($b('marketPrice').value)*100),pickupAddress:$b('marketPickupAddress').value.trim(),pickupInstructions:$b('marketPickupInstructions').value.trim(),pickupLat:$b('marketPickupLat').value===''?null:Number($b('marketPickupLat').value),pickupLng:$b('marketPickupLng').value===''?null:Number($b('marketPickupLng').value)}}
async function saveRide(){if(operatorBusy||!operatorAuth||!$b('marketRideForm').reportValidity())return;operatorBusy=true;$b('saveMarketRide').disabled=true;$b('rideFormError').textContent='';try{const fields=rideFields(),data=editingRide?await api('/api/rides/'+editingRide.id,{token:operatorAuth.token,body:{...fields,action:'update',expectedRevision:editingRide.revision}}):await api('/api/rides',{token:operatorAuth.token,body:{...fields,requestId:rideRequestId,publish:$b('marketPublish').checked}});operatorRideId=data.ride.id;cancelEdit();operatorRenderKey='';await refreshOperator();await loadCatalog();notify('Viaje guardado y sincronizado.');}catch(error){$b('rideFormError').textContent=error.message;}finally{operatorBusy=false;$b('saveMarketRide').disabled=false;}}
function editRide(id){const r=operatorData.rides.find(r=>r.id===id);if(!r)return;editingRide=r;rideFormOpen=true;$b('marketRideForm').hidden=false;for(const [key,value] of Object.entries({marketFrom:r.origin,marketTo:r.destination,marketDate:r.date,marketTime:r.time,marketVehicleType:r.vehicleType,marketVehicle:r.vehicle,marketCapacity:r.capacity,marketPrice:r.priceCents/100,marketPickupAddress:r.pickupAddress||r.origin,marketPickupInstructions:r.pickupInstructions||'Presentarse 15 minutos antes.',marketPickupLat:r.pickupLat??'',marketPickupLng:r.pickupLng??''}))$b(key).value=value;$b('rideFormTitle').textContent='Editar viaje';$b('saveMarketRide').textContent='Guardar cambios';$b('marketPublishLabel').hidden=true;$b('cancelRideEdit').hidden=false;$b('rideFormError').textContent=r.occupied?'Con reservas puedes ajustar precio y capacidad; se conserva ruta, horario y vehículo.':'';$b('marketRideForm').scrollIntoView({behavior:'smooth',block:'start'});}
function cancelEdit(){editingRide=null;rideFormOpen=false;if(operatorData?.rides.length)$b('marketRideForm').hidden=true;rideRequestId=crypto.randomUUID();$b('rideFormTitle').textContent='Crear viaje';$b('saveMarketRide').textContent='Publicar viaje';$b('marketPublishLabel').hidden=false;$b('cancelRideEdit').hidden=true;$b('rideFormError').textContent='';}
async function rideAction(id,action){if(operatorBusy)return;if(action==='cancel'&&!window.confirm('¿Cancelar este viaje de demostración y reembolsar sus reservas simuladas?'))return;operatorBusy=true;try{await api('/api/rides/'+id,{token:operatorAuth.token,body:{action}});operatorRenderKey='';await refreshOperator();await loadCatalog();notify(action==='start'?'Recorrido iniciado. Los pasajeros ya pueden seguirlo.':'Viaje actualizado.');}catch(error){notify(error.message);}finally{operatorBusy=false;}}
async function bookingAction(id,body,asOperator){const token=asOperator?operatorAuth?.token:ticketKeys[id]||activeTicketToken;try{const data=await api('/api/bookings/'+id,{token,body});if(activeTicket?.id===id){activeTicket=data.booking;ticketRenderKey='';renderTicket();}operatorRenderKey='';if(operatorAuth&&currentScreen()==='operator')await refreshOperator();await loadCatalog();if(currentScreen()==='mytrip')await loadHistory();notify('Reserva actualizada y sincronizada.');}catch(error){notify(error.message);}}
async function cancelBooking(id,asOperator=false){if(!window.confirm('¿Cancelar esta reserva de demostración? Sus asientos volverán a estar disponibles y se registrará un reembolso simulado.'))return;await bookingAction(id,{action:'cancel'},asOperator);}
async function poll(){clearTimeout(pollTimer);if(polling)return;polling=true;try{if(!document.hidden){await loadCatalog();const screen=currentScreen();if(screen==='operator'&&operatorAuth&&operatorTier!=='premium')await refreshOperator();if(screen==='ticket'&&activeTicket)await loadTicket(activeTicket.id,activeTicketToken);if(screen==='mytrip')await loadHistory();}}finally{polling=false;pollTimer=setTimeout(poll,POLL_INTERVAL_MS);}}
async function routeBookingHash(){const hash=location.hash.slice(1),m=hash.match(/^(boleto|salida)\/([a-f0-9-]{36})(?:\?(.*))?$/);if(!m)return;const [,kind,id,query]=m;if(kind==='boleto'){show('ticket');activeTicket=null;ticketRenderKey='';await loadTicket(id,new URLSearchParams(query||'').get('key'));}else{await loadCatalog();const r=catalog.find(r=>r.id===id);if(!r)return notify('La salida no está publicada o ya no existe.');selectedRideId=id;show('detail');}const splash=$b('splash');if(splash){splash.style.display='none';splash.setAttribute('aria-hidden','true');}}
window.BookingApp={claimPrivateRequest,sendPrivateRequest,openPrivateRequest,demoSeat,demoPaymentContinue,demoPaymentBack,chooseTier:chooseOperatorTier,premiumDetail,fleetDemoSelect,passengerFilter(value){passengerSort=value;renderResults();},companyFilter(value){passengerCompany=value;renderResults();},favoriteOperator:toggleOperatorFavorite,saveBrand,operatorSection:selectOperatorSection,openScanner:openBoardingScanner,closeScanner:closeBoardingScanner,validateQR:validateBoardingQR,newRide(){cancelEdit();rideFormOpen=true;$b('marketRideForm').hidden=false;$b('marketRideForm').scrollIntoView({behavior:'smooth',block:'start'});},editOperatorProfile(){profileEditing=!profileEditing;$b('marketProfileForm').hidden=!profileEditing;},renderResults,renderDetail,renderCheckout,pay,renderHistory,openOperator,saveOperator,saveRide,editRide,cancelEdit,rideAction,choose,allDepartures(){showAll=true;renderResults();},vehiclePreset(type){$b('marketVehicle').value=({van:'Mercedes Sprinter',minivan:'Hyundai H1',suv:'Kia Sorento',auto:'Toyota Corolla'})[type];},filterRides(value){operatorFilter=value;operatorRenderKey='';document.querySelectorAll('[data-operator-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.operatorFilter===value));renderOperatorData();},selectOperatorRide(id){operatorRideId=id;renderReservations();$b('operatorReservationsTitle').scrollIntoView({behavior:'smooth',block:'start'});},board(id,index){bookingAction(id,{action:'board',passengerIndex:index},true);},cancelBooking,cancelCurrent(){if(activeTicket)cancelBooking(activeTicket.id);},openTicket(id){const key=ticketKeys[id];if(!key)return;location.hash='boleto/'+id+'?key='+encodeURIComponent(key);},async shareCurrentTicket(){if(!activeTicket)return;try{await navigator.clipboard.writeText(ticketLink(activeTicket,activeTicketToken));notify('Enlace privado del boleto copiado.');}catch{notify('Puedes copiar la dirección del boleto desde el navegador.');}},async copyRide(id){try{await navigator.clipboard.writeText(rideLink(id));notify('Enlace público de salida copiado.');}catch{notify(rideLink(id));}},followTicket(){if(activeTicket?.status==='confirmed'&&activeTicket.ride.liveId)window.LiveTrip?.openLinked(activeTicket.ride.liveId,activeTicketToken);},followOperator(id){const r=operatorData?.rides.find(r=>r.id===id);if(r?.liveId)window.LiveTrip?.openLinked(r.liveId,operatorAuth.token);},async attendSOS(id){const r=operatorData?.rides.find(r=>r.id===id);if(!r?.liveId)return;try{const data=await api('/api/trips/'+r.liveId,{token:operatorAuth.token});await api('/api/trips/'+r.liveId+'/commands',{token:operatorAuth.token,body:{action:'attend',alertId:r.activeAlert.id,requestId:crypto.randomUUID(),expectedRevision:data.trip.revision}});operatorRenderKey='';await refreshOperator();}catch(error){notify(error.message);}}};
window.select=choose;window.cycle=n=>{if(!fleet.length)return;selected=(selected+n+fleet.length)%fleet.length;selectedRideId=fleet[selected].id;checkoutBuilt='';renderDetail();};
